using System.Diagnostics;
using System.Diagnostics.Metrics;

namespace OtelDemo.Telemetry;

/// <summary>
/// Central place for all custom ActivitySources and Meters.
/// The names defined here must match what is registered in Program.cs.
/// </summary>
public static class DiagnosticsConfig
{
    public const string ServiceName = "OtelDemo";

    // --- Tracing ---
    public static readonly ActivitySource ActivitySource = new(ServiceName);

    // --- Metrics ---
    public static readonly Meter Meter = new(ServiceName);

    public static readonly Counter<long> OrdersProcessed =
        Meter.CreateCounter<long>(
            "orders.processed",
            unit: "{order}",
            description: "Number of orders that have been processed");
}

using System.Diagnostics;
using OtelDemo.Telemetry;

namespace OtelDemo.Services;

public class OrderService
{
    private readonly ILogger<OrderService> _logger;
    private readonly HttpClient _httpClient;

    public OrderService(ILogger<OrderService> logger, HttpClient httpClient)
    {
        _logger = logger;
        _httpClient = httpClient;
    }

    public async Task<string> ProcessOrderAsync(string orderId)
    {
        // Start a custom span for the entire order-processing workflow.
        using var activity = DiagnosticsConfig.ActivitySource.StartActivity(
            "ProcessOrder",
            ActivityKind.Internal);

        // Attach business-relevant attributes to the span.
        activity?.SetTag("order.id", orderId);

        try
        {
            await ValidateOrderAsync(orderId);
            await ChargePaymentAsync(orderId);

            // Record the successful processing in the counter metric.
            DiagnosticsConfig.OrdersProcessed.Add(1,
                new KeyValuePair<string, object?>("order.status", "success"));

            activity?.SetTag("order.status", "success");
            return $"Order {orderId} processed successfully";
        }
        catch (Exception ex)
        {
            activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
            activity?.RecordException(ex);

            DiagnosticsConfig.OrdersProcessed.Add(1,
                new KeyValuePair<string, object?>("order.status", "failure"));

            throw;
        }
    }

    private async Task ValidateOrderAsync(string orderId)
    {
        // Child span for validation step.
        using var activity = DiagnosticsConfig.ActivitySource.StartActivity("ValidateOrder");
        activity?.SetTag("order.id", orderId);

        // Simulate validation work.
        await Task.Delay(50);

        _logger.LogInformation("Order {OrderId} validated", orderId);
    }

    private async Task ChargePaymentAsync(string orderId)
    {
        // Child span that also shows an outgoing HTTP call being traced automatically.
        using var activity = DiagnosticsConfig.ActivitySource.StartActivity("ChargePayment");
        activity?.SetTag("order.id", orderId);

        // The HttpClient instrumentation will create its own child span for this call.
        try
        {
            await _httpClient.PostAsync(
                "https://localhost:5001/payments",
                new StringContent($"{{\"orderId\":\"{orderId}\"}}"));
        }
        catch (HttpRequestException)
        {
            // Tolerate connectivity failures in this demo.
            _logger.LogWarning("Payment gateway unreachable – continuing for demo purposes");
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using OtelDemo.Services;

namespace OtelDemo.Controllers;

[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    private readonly OrderService _orderService;

    public OrdersController(OrderService orderService)
    {
        _orderService = orderService;
    }

    [HttpPost("{orderId}")]
    public async Task<IActionResult> Process(string orderId)
    {
        var result = await _orderService.ProcessOrderAsync(orderId);
        return Ok(new { message = result });
    }
}

