using OpenTelemetry.Metrics;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;
using OtelDemo.Services;
using OtelDemo.Telemetry;

var builder = WebApplication.CreateBuilder(args);

// ---------- Services ----------
builder.Services.AddControllers();
builder.Services.AddOpenApi();

// Register OrderService + its typed HttpClient.
builder.Services.AddHttpClient<OrderService>();

// ---------- OpenTelemetry ----------
var otlpEndpoint = builder.Configuration.GetValue<string>("Otlp:Endpoint")
                   ?? "http://localhost:4317";

builder.Services
    .AddOpenTelemetry()
    .ConfigureResource(res => res.AddService(
        serviceName: DiagnosticsConfig.ServiceName,
        serviceVersion: typeof(Program).Assembly.GetName().Version?.ToString() ?? "1.0.0"))
    // Distributed tracing
    .WithTracing(tracing => tracing
        .AddAspNetCoreInstrumentation()      // auto-instrument incoming HTTP requests
        .AddHttpClientInstrumentation()       // auto-instrument outgoing HttpClient calls
        .AddSource(DiagnosticsConfig.ServiceName) // listen for our custom ActivitySource
        .AddOtlpExporter(opts => opts.Endpoint = new Uri(otlpEndpoint)))
    // Metrics
    .WithMetrics(metrics => metrics
        .AddAspNetCoreInstrumentation()      // request duration, active requests, etc.
        .AddHttpClientInstrumentation()       // outgoing call duration
        .AddMeter(DiagnosticsConfig.ServiceName)  // our custom Meter (orders.processed counter)
        .AddOtlpExporter(opts => opts.Endpoint = new Uri(otlpEndpoint)));

var app = builder.Build();

if (app.Environment.IsDevelopment())
{
    app.MapOpenApi();
}

app.UseAuthorization();
app.MapControllers();
app.Run();

