using OpenTelemetry.Metrics;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;
using OtelDemo;
using OtelDemo.Services;

var builder = WebApplication.CreateBuilder(args);

// ── HttpClient for OrderService (auto-instrumented) ──────────────────────
builder.Services.AddHttpClient<OrderService>();

// ── OpenTelemetry ────────────────────────────────────────────────────────
builder.Services.AddOpenTelemetry()
    .ConfigureResource(res => res
        .AddService(
            serviceName: TelemetryConstants.ServiceName,
            serviceVersion: typeof(Program).Assembly.GetName().Version?.ToString() ?? "1.0.0"))
    .WithTracing(tracing => tracing
        // Auto-instrument inbound ASP.NET Core requests
        .AddAspNetCoreInstrumentation()
        // Auto-instrument outbound HttpClient calls
        .AddHttpClientInstrumentation()
        // Subscribe to our custom ActivitySource
        .AddSource(TelemetryConstants.ServiceName)
        // Export traces via OTLP (default: http://localhost:4317)
        .AddOtlpExporter())
    .WithMetrics(metrics => metrics
        // Built-in ASP.NET Core & HttpClient metrics
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        // Subscribe to our custom Meter
        .AddMeter(TelemetryConstants.ServiceName)
        // Export metrics via OTLP
        .AddOtlpExporter());

var app = builder.Build();

app.UseHttpsRedirection();

// ── Endpoints ────────────────────────────────────────────────────────────
app.MapGet("/weatherforecast", () =>
{
    var summaries = new[]
    {
        "Freezing", "Bracing", "Chilly", "Cool", "Mild", "Warm", "Balmy", "Hot", "Sweltering", "Scorching"
    };

    return Enumerable.Range(1, 5).Select(index =>
        new WeatherForecast(
            DateOnly.FromDateTime(DateTime.Now.AddDays(index)),
            Random.Shared.Next(-20, 55),
            summaries[Random.Shared.Next(summaries.Length)]
        )).ToArray();
});

app.MapPost("/orders/{id}", async (string id, OrderService orderService, CancellationToken ct) =>
{
    var result = await orderService.ProcessOrderAsync(id, ct);
    return Results.Ok(new { message = result });
});

app.Run();

record WeatherForecast(DateOnly Date, int TemperatureC, string? Summary)
{
    public int TemperatureF => 32 + (int)(TemperatureC / 0.5556);
}

