 using System.Diagnostics;
 using System.Diagnostics.Metrics;

 namespace OtelDemo.Services;

 public sealed class OrderService
 {
     private static readonly Counter<long> OrdersProcessed =
         TelemetryConstants.Meter.CreateCounter<long>(
             "orders.processed",
             unit: "{order}",
             description: "Number of orders processed");

     private readonly ILogger<OrderService> _logger;
     private readonly HttpClient _httpClient;

     public OrderService(ILogger<OrderService> logger, HttpClient httpClient)
     {
         _logger = logger;
         _httpClient = httpClient;
     }

     public async Task<string> ProcessOrderAsync(string orderId, CancellationToken ct = default)
     {
         // Start a custom span for the business operation
         using var activity = TelemetryConstants.ActivitySource.StartActivity(
             "ProcessOrder",
             ActivityKind.Internal);

         // Add structured attributes to the span
         activity?.SetTag("order.id", orderId);

         try
         {
             // Simulate validation sub-span
             await ValidateOrderAsync(orderId, ct);

             // Outgoing HTTP call – auto-instrumented by OpenTelemetry.Instrumentation.Http
             var response = await _httpClient.GetAsync(
                 $"https://httpbin.org/get?orderId={orderId}", ct);
             response.EnsureSuccessStatusCode();

             activity?.SetTag("order.status", "completed");

             // Increment the custom counter metric
             OrdersProcessed.Add(1,
                 new KeyValuePair<string, object?>("order.status", "completed"));

             _logger.LogInformation("Order {OrderId} processed successfully", orderId);
             return $"Order {orderId} completed";
         }
         catch (Exception ex)
         {
             activity?.SetStatus(ActivityStatusCode.Error, ex.Message);
             activity?.AddException(ex);

             OrdersProcessed.Add(1,
                 new KeyValuePair<string, object?>("order.status", "failed"));

             throw;
         }
     }

     private static async Task ValidateOrderAsync(string orderId, CancellationToken ct)
     {
         using var activity = TelemetryConstants.ActivitySource.StartActivity("ValidateOrder");
         activity?.SetTag("order.id", orderId);

         // Simulate some validation work
         await Task.Delay(50, ct);
     }
 }

